-- N2 read dependencies and N3 recommendation storage. No demo family or recipes.
CREATE TABLE ingredient_allergen_tags(ingredient_id BIGINT NOT NULL REFERENCES ingredients(id), allergen_code TEXT NOT NULL, source_type TEXT NOT NULL DEFAULT 'unknown', confidence DOUBLE PRECISION, label_required BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(ingredient_id,allergen_code));
CREATE TABLE allergen_aliases(alias TEXT PRIMARY KEY, allergen_code TEXT NOT NULL, source_type TEXT NOT NULL DEFAULT 'unknown', confidence DOUBLE PRECISION);
CREATE TABLE ingredient_storage_guidelines(ingredient_id BIGINT REFERENCES ingredients(id), guideline TEXT);
CREATE TABLE meal_records(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, session_id BIGINT REFERENCES meal_sessions(id), recipe_id BIGINT REFERENCES recipes(id), eaten_at TEXT NOT NULL);
CREATE TABLE meal_record_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, record_id BIGINT REFERENCES meal_records(id), member_id BIGINT REFERENCES members(id), servings DOUBLE PRECISION NOT NULL);
CREATE TABLE nutrition_intakes(record_item_id BIGINT REFERENCES meal_record_items(id), nutrient TEXT, amount DOUBLE PRECISION);
CREATE TABLE recommendation_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, household_id BIGINT REFERENCES households(id), request_json TEXT, result_json TEXT, created_at TEXT DEFAULT (CURRENT_TIMESTAMP::text));
CREATE TABLE recommendation_candidates(request_id BIGINT REFERENCES recommendation_requests(id), recipe_id BIGINT REFERENCES recipes(id), rank BIGINT, candidate_json TEXT);
CREATE TABLE metadata(key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE recommendation_feedback(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, recommendation_request_id BIGINT NOT NULL REFERENCES recommendation_requests(id), candidate_recipe_id BIGINT REFERENCES recipes(id), member_id BIGINT REFERENCES members(id), action TEXT NOT NULL CHECK(action IN ('shown','selected','rejected','cooked','skipped','rated')), rating BIGINT CHECK(rating BETWEEN 1 AND 5), reason_code TEXT, reason_text TEXT, created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text));
CREATE TABLE preference_evidence(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, household_id BIGINT NOT NULL REFERENCES households(id), member_id BIGINT REFERENCES members(id), source_type TEXT NOT NULL, feature_type TEXT NOT NULL, feature_value TEXT NOT NULL, signal TEXT NOT NULL CHECK(signal IN ('prefer','avoid','neutral')), strength DOUBLE PRECISION NOT NULL, confidence DOUBLE PRECISION NOT NULL, observed_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text), expires_at TEXT, metadata_json TEXT);
CREATE TABLE inferred_preferences(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, household_id BIGINT NOT NULL REFERENCES households(id), member_id BIGINT REFERENCES members(id), feature_type TEXT NOT NULL, feature_value TEXT NOT NULL, inference TEXT NOT NULL, confidence DOUBLE PRECISION NOT NULL, evidence_count BIGINT NOT NULL, score_adjustment DOUBLE PRECISION NOT NULL, first_observed_at TEXT NOT NULL, last_observed_at TEXT NOT NULL, expires_at TEXT, source_summary TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','expired','dismissed')));
CREATE TABLE household_behavior_summary(household_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY REFERENCES households(id), preferred_cook_time_minutes DOUBLE PRECISION, preferred_meal_types_json TEXT, frequently_used_ingredients_json TEXT, recently_rejected_features_json TEXT, updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text));
CREATE TABLE data_sources(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_key TEXT NOT NULL UNIQUE, provider_name TEXT NOT NULL, dataset_name TEXT NOT NULL, source_url TEXT NOT NULL, license_text TEXT, license_url TEXT, expected_format TEXT NOT NULL, enabled BIGINT NOT NULL DEFAULT 1);
CREATE TABLE dataset_releases(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, data_source_id BIGINT NOT NULL REFERENCES data_sources(id), external_release_id TEXT, source_published_at TEXT, imported_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text), checksum TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('staging','validated','published','retired','failed')), record_count BIGINT NOT NULL DEFAULT 0, accepted_count BIGINT NOT NULL DEFAULT 0, quarantined_count BIGINT NOT NULL DEFAULT 0, notes TEXT);
CREATE TABLE official_food_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, release_id BIGINT NOT NULL REFERENCES dataset_releases(id), source_food_code TEXT NOT NULL, food_name TEXT NOT NULL, normalized_name TEXT NOT NULL, food_category TEXT, manufacturer TEXT, product_report_number TEXT, serving_reference TEXT, basis_amount_g DOUBLE PRECISION, source_record_date TEXT, active BIGINT NOT NULL DEFAULT 1, UNIQUE(release_id,source_food_code));
CREATE TABLE official_nutrient_values(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, official_food_item_id BIGINT NOT NULL REFERENCES official_food_items(id), nutrient_code TEXT NOT NULL, amount DOUBLE PRECISION NOT NULL, unit TEXT NOT NULL, basis_amount_g DOUBLE PRECISION, confidence DOUBLE PRECISION, source_field TEXT, UNIQUE(official_food_item_id,nutrient_code));
CREATE TABLE ingredient_official_food_mappings(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, ingredient_id BIGINT NOT NULL REFERENCES ingredients(id), official_food_item_id BIGINT NOT NULL REFERENCES official_food_items(id), mapping_method TEXT NOT NULL CHECK(mapping_method IN ('manual','approved_alias','imported_code')), mapping_confidence DOUBLE PRECISION NOT NULL, approved_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text), active BIGINT NOT NULL DEFAULT 1, UNIQUE(ingredient_id,official_food_item_id));
CREATE TABLE allergen_reference_versions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_name TEXT NOT NULL, source_url TEXT NOT NULL, legal_or_reference_version TEXT NOT NULL, effective_date TEXT, imported_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text), checksum TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('staging','validated','published','retired','failed')));
CREATE TABLE allergen_reference_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version_id BIGINT NOT NULL REFERENCES allergen_reference_versions(id), allergen_code TEXT NOT NULL, display_name_ko TEXT NOT NULL, aliases_json TEXT NOT NULL DEFAULT '[]', active BIGINT NOT NULL DEFAULT 1, UNIQUE(version_id,allergen_code));
CREATE TABLE data_release_pointers(id BIGINT PRIMARY KEY CHECK(id=1), nutrition_release_id BIGINT REFERENCES dataset_releases(id), allergen_reference_version_id BIGINT REFERENCES allergen_reference_versions(id), updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text));
ALTER TABLE ingredient_storage_guidelines ADD COLUMN unopened_days INTEGER;
ALTER TABLE ingredient_storage_guidelines ADD COLUMN opened_days INTEGER;
ALTER TABLE ingredient_storage_guidelines ADD COLUMN frozen_days INTEGER;
ALTER TABLE ingredient_storage_guidelines ADD COLUMN recommended_storage TEXT;
ALTER TABLE ingredient_storage_guidelines ADD COLUMN id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY;
ALTER TABLE inventory_items ADD COLUMN storage_location TEXT;
ALTER TABLE inventory_items ADD COLUMN package_state TEXT;
ALTER TABLE recommendation_requests ADD COLUMN nutrition_data_release_id BIGINT REFERENCES dataset_releases(id);
ALTER TABLE recommendation_requests ADD COLUMN allergen_reference_version_id BIGINT REFERENCES allergen_reference_versions(id);
CREATE UNIQUE INDEX preference_identity ON inferred_preferences(household_id,coalesce(member_id,0),feature_type,feature_value);
INSERT INTO data_release_pointers(id) VALUES (1);
INSERT INTO metadata(key,value) VALUES ('db_version','postgres-recommendation-v1'),('dataset_mode','private');

REVOKE ALL ON ingredient_allergen_tags, allergen_aliases, ingredient_storage_guidelines, meal_records, meal_record_items, nutrition_intakes, recommendation_requests, recommendation_candidates, metadata, recommendation_feedback, preference_evidence, inferred_preferences, household_behavior_summary, data_sources, dataset_releases, official_food_items, official_nutrient_values, ingredient_official_food_mappings, allergen_reference_versions, allergen_reference_items, data_release_pointers FROM PUBLIC;
